function(container, apiUrl, tables) {
  let selectedProducts = [];
  let stores = [];
  let products = [];
  let categories = [];
  let predictions = [];
  let salesHistory = [];

  // 初期データの設定
  function initializeData() {
    stores = tables.find(t => t.tableName === '店舗マスタ')?.records || [];
    products = tables.find(t => t.tableName === '商品マスタ')?.records || [];
    predictions = tables.find(t => t.tableName === '需要予測結果')?.records || [];
    salesHistory = tables.find(t => t.tableName === '売上実績データ')?.records || [];

    // カテゴリ一覧を取得
    categories = [...new Set(products.map(p => p.商品カテゴリID))].filter(Boolean);

    renderStoreOptions();
    renderCategoryOptions();

    // 今日の日付を設定
    const today = new Date().toISOString().split('T')[0];
    container.querySelector('#order-date').value = today;

    // 納期は3日後を初期値に設定
    const deliveryDate = new Date();
    deliveryDate.setDate(deliveryDate.getDate() + 3);
    container.querySelector('#delivery-date').value = deliveryDate.toISOString().split('T')[0];
  }

  // 店舗選択肢を描画
  function renderStoreOptions() {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.filter(s => s.有効フラグ).forEach(store => {
      storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
    });
  }

  // カテゴリ選択肢を描画
  function renderCategoryOptions() {
    const categorySelect = container.querySelector('#category-select');
    categorySelect.innerHTML = '<option value="">全カテゴリ</option>';
    categories.forEach(categoryId => {
      categorySelect.innerHTML += `<option value="${categoryId}">カテゴリ${categoryId}</option>`;
    });
  }

  // 商品一覧を描画
  function renderProductList(productList) {
    const tbody = container.querySelector('#product-list');
    tbody.innerHTML = productList.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === container.querySelector('#store-select').value);
      const predictedQty = prediction ? prediction.予測数量 : 0;
      const isSelected = selectedProducts.some(p => p.商品ID === product.商品ID);

      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" ${isSelected ? 'checked' : ''} data-product-id="${product.商品ID}"></td>
          <td>${product.商品名 || ''}</td>
          <td>${product.商品コード || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>${predictedQty}</td>
          <td>100</td>
          <td><button class="action-btn secondary add-to-order-btn" data-product-id="${product.商品ID}">追加</button></td>
        </tr>
      `;
    }).join('');
  }

  // 発注商品一覧を描画
  function renderOrderList() {
    const tbody = container.querySelector('#order-list');
    tbody.innerHTML = selectedProducts.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === container.querySelector('#store-select').value);
      const predictedQty = prediction ? prediction.予測数量 : 0;
      const manualQty = product.手動調整数量 || predictedQty;
      const subtotal = manualQty * (product.単価 || 0);

      return `
        <tr data-id="${product.商品ID}">
          <td>${product.商品名 || ''}</td>
          <td>${product.商品コード || ''}</td>
          <td>¥${(product.単価 || 0).toLocaleString()}</td>
          <td>${predictedQty}</td>
          <td><input type="number" class="input manual-qty-input" value="${manualQty}" min="0" data-product-id="${product.商品ID}"></td>
          <td>¥${subtotal.toLocaleString()}</td>
          <td><button class="action-btn secondary prediction-detail-btn" data-product-id="${product.商品ID}">予測根拠</button></td>
          <td><button class="action-btn secondary remove-btn" data-product-id="${product.商品ID}">削除</button></td>
        </tr>
      `;
    }).join('');

    updateTotalAmount();
  }

  // 発注総額を更新
  function updateTotalAmount() {
    const total = selectedProducts.reduce((sum, product) => {
      const qty = product.手動調整数量 || 0;
      return sum + (qty * (product.単価 || 0));
    }, 0);
    container.querySelector('#total-amount').textContent = `¥${total.toLocaleString()}`;
  }

  // 商品検索
  function searchProducts() {
    const keyword = container.querySelector('#product-search').value.toLowerCase();
    const categoryId = container.querySelector('#category-select').value;

    let filteredProducts = products.filter(p => p.有効フラグ && p.AI予測対象フラグ);

    if (keyword) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 || '').toLowerCase().includes(keyword) || 
        (p.商品コード || '').toLowerCase().includes(keyword)
      );
    }

    if (categoryId) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
    }

    renderProductList(filteredProducts);
  }

  // 商品を発注リストに追加
  function addToOrder(productId) {
    const product = products.find(p => p.商品ID === productId);
    if (product && !selectedProducts.some(p => p.商品ID === productId)) {
      const prediction = predictions.find(p => p.商品ID === productId && p.店舗ID === container.querySelector('#store-select').value);
      const predictedQty = prediction ? prediction.予測数量 : 1;

      selectedProducts.push({
        ...product,
        手動調整数量: predictedQty
      });
      renderOrderList();
      searchProducts(); // 商品リストを更新
    }
  }

  // 商品を発注リストから削除
  function removeFromOrder(productId) {
    selectedProducts = selectedProducts.filter(p => p.商品ID !== productId);
    renderOrderList();
    searchProducts(); // 商品リストを更新
  }

  // 予測根拠詳細を表示
  function showPredictionDetails(productId) {
    const product = products.find(p => p.商品ID === productId);
    const prediction = predictions.find(p => p.商品ID === productId && p.店舗ID === container.querySelector('#store-select').value);
    const history = salesHistory.filter(s => s.商品ID === productId && s.店舗ID === container.querySelector('#store-select').value).slice(-30);

    const modal = container.querySelector('#prediction-modal');
    const details = container.querySelector('#prediction-details');

    details.innerHTML = `
      <div style="margin-bottom: 16px;">
        <h4>${product?.商品名 || '商品名不明'}</h4>
        <p class="muted">商品コード: ${product?.商品コード || 'N/A'}</p>
      </div>

      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 16px; margin-bottom: 16px;">
        <div class="card">
          <div class="card-body">
            <h5>予測情報</h5>
            <p>予測数量: ${prediction?.予測数量 || 0}個</p>
            <p>予測精度: ${prediction?.予測精度 || 0}%</p>
            <p>推奨発注数量: ${prediction?.推奨発注数量 || 0}個</p>
          </div>
        </div>
        <div class="card">
          <div class="card-body">
            <h5>過去30日の売上実績</h5>
            <p>平均売上数量: ${history.length > 0 ? Math.round(history.reduce((sum, h) => sum + h.販売数量, 0) / history.length) : 0}個/日</p>
            <p>最大売上数量: ${history.length > 0 ? Math.max(...history.map(h => h.販売数量)) : 0}個</p>
            <p>データ件数: ${history.length}件</p>
          </div>
        </div>
      </div>

      <div class="card">
        <div class="card-body">
          <h5>予測要因</h5>
          <ul>
            <li>季節性: ${product?.季節性フラグ ? '季節変動あり' : '季節変動なし'}</li>
            <li>モデルバージョン: ${prediction?.予測モデルバージョン || 'v1.0'}</li>
            <li>予測ステータス: ${prediction?.予測ステータス || '完了'}</li>
          </ul>
        </div>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 在庫状況確認を表示
  function showInventoryStatus() {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const modal = container.querySelector('#inventory-modal');
    const details = container.querySelector('#inventory-details');

    const inventoryData = selectedProducts.map(product => {
      const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === storeId);
      return {
        ...product,
        現在庫: 100, // サンプル値
        安全在庫: 20, // サンプル値
        予測数量: prediction?.予測数量 || 0,
        リードタイム: product.リードタイム日数 || 3
      };
    });

    details.innerHTML = `
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>現在庫</th>
              <th>安全在庫</th>
              <th>予測数量</th>
              <th>リードタイム</th>
              <th>推奨発注数</th>
            </tr>
          </thead>
          <tbody>
            ${inventoryData.map(item => `
              <tr>
                <td>${item.商品名}</td>
                <td>${item.現在庫}</td>
                <td>${item.安全在庫}</td>
                <td>${item.予測数量}</td>
                <td>${item.リードタイム}日</td>
                <td>${Math.max(0, item.予測数量 + item.安全在庫 - item.現在庫)}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // 過去実績参照を表示
  function showSalesHistory() {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const modal = container.querySelector('#history-modal');
    const details = container.querySelector('#history-details');

    const historyData = selectedProducts.map(product => {
      const history = salesHistory.filter(s => s.商品ID === product.商品ID && s.店舗ID === storeId).slice(-90);
      const last30Days = history.slice(-30);
      const last60Days = history.slice(-60, -30);
      const last90Days = history.slice(-90, -60);

      return {
        商品名: product.商品名,
        過去30日: last30Days.reduce((sum, h) => sum + h.販売数量, 0),
        過去60日: last60Days.reduce((sum, h) => sum + h.販売数量, 0),
        過去90日: last90Days.reduce((sum, h) => sum + h.販売数量, 0),
        平均: Math.round((last30Days.reduce((sum, h) => sum + h.販売数量, 0) + last60Days.reduce((sum, h) => sum + h.販売数量, 0) + last90Days.reduce((sum, h) => sum + h.販売数量, 0)) / 3)
      };
    });

    details.innerHTML = `
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>過去30日売上</th>
              <th>過去60日売上</th>
              <th>過去90日売上</th>
              <th>3ヶ月平均</th>
            </tr>
          </thead>
          <tbody>
            ${historyData.map(item => `
              <tr>
                <td>${item.商品名}</td>
                <td>${item.過去30日}</td>
                <td>${item.過去60日}</td>
                <td>${item.過去90日}</td>
                <td>${item.平均}</td>
              </tr>
            `).join('')}
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      alert('発注日付を入力してください');
      return false;
    }

    if (!deliveryDate) {
      alert('納期を指定してください');
      return false;
    }

    if (new Date(deliveryDate) <= new Date(orderDate)) {
      alert('納期は発注日より後の日付を指定してください');
      return false;
    }

    if (selectedProducts.length === 0) {
      alert('発注する商品を選択してください');
      return false;
    }

    // 数量チェック
    for (const product of selectedProducts) {
      const qty = product.手動調整数量;
      if (!qty || qty <= 0) {
        alert(`${product.商品名}の発注数量は1以上で入力してください`);
        return false;
      }
      if (isNaN(qty)) {
        alert(`${product.商品名}の発注数量は数値で入力してください`);
        return false;
      }
    }

    return true;
  }

  // 発注書作成
  async function createOrder() {
    if (!validateForm()) return;

    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    try {
      // 各商品の発注データを作成
      for (const product of selectedProducts) {
        const prediction = predictions.find(p => p.商品ID === product.商品ID && p.店舗ID === storeId);

        const orderData = {
          店舗ID: storeId,
          商品ID: product.商品ID,
          需要予測結果ID: prediction?.予測結果ID || null,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(deliveryDate).toISOString(),
          発注数量: product.手動調整数量,
          予測数量: prediction?.予測数量 || 0,
          発注単価: product.単価,
          発注金額: product.手動調整数量 * product.単価,
          発注方法: prediction ? 'AI推奨修正' : '手動発注',
          発注ステータス: '発注済',
          仕入先ID: product.仕入先ID,
          発注理由: 'AI需要予測に基づく発注',
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        const saved = await window.aivicApi.save(7, orderData); // 発注データテーブル
        if (!saved) {
          alert('発注書の作成に失敗しました');
          return;
        }
      }

      alert('発注書が正常に作成されました');

      // 発注管理画面に遷移
      window.showScreen('scr-1778591852463');

    } catch (error) {
      console.error('発注書作成エラー:', error);
      alert('発注書の作成中にエラーが発生しました');
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-search-products').addEventListener('click', searchProducts);

  container.querySelector('#btn-check-inventory').addEventListener('click', showInventoryStatus);
  container.querySelector('#btn-view-history').addEventListener('click', showSalesHistory);
  container.querySelector('#btn-calculate-total').addEventListener('click', updateTotalAmount);

  container.querySelector('#btn-create-order').addEventListener('click', createOrder);
  container.querySelector('#btn-cancel').addEventListener('click', () => {
    if (confirm('作成中の発注書を破棄しますか？')) {
      window.showScreen('scr-1778591852463');
    }
  });

  // モーダル閉じるボタン
  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#prediction-modal').classList.add('hidden');
  });
  container.querySelector('#btn-close-inventory-modal').addEventListener('click', () => {
    container.querySelector('#inventory-modal').classList.add('hidden');
  });
  container.querySelector('#btn-close-history-modal').addEventListener('click', () => {
    container.querySelector('#history-modal').classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    // 商品追加ボタン
    const addBtn = e.target.closest('.add-to-order-btn');
    if (addBtn) {
      addToOrder(addBtn.dataset.productId);
      return;
    }

    // 商品削除ボタン
    const removeBtn = e.target.closest('.remove-btn');
    if (removeBtn) {
      removeFromOrder(removeBtn.dataset.productId);
      return;
    }

    // 予測根拠ボタン
    const predictionBtn = e.target.closest('.prediction-detail-btn');
    if (predictionBtn) {
      showPredictionDetails(predictionBtn.dataset.productId);
      return;
    }
  });

  // チェックボックス変更イベント
  container.addEventListener('change', (e) => {
    if (e.target.classList.contains('product-checkbox')) {
      const productId = e.target.dataset.productId;
      if (e.target.checked) {
        addToOrder(productId);
      } else {
        removeFromOrder(productId);
      }
    }

    // 手動調整数量変更
    if (e.target.classList.contains('manual-qty-input')) {
      const productId = e.target.dataset.productId;
      const qty = parseInt(e.target.value) || 0;
      const product = selectedProducts.find(p => p.商品ID === productId);
      if (product) {
        product.手動調整数量 = qty;
        updateTotalAmount();
      }
    }
  });

  // 初期化
  initializeData();
  searchProducts();
}
